export function ButtonElement({
  label = "{{label}}",
  type = "{{type}}",
  accent = "{{accent}}",
  disabled = {{disabled}},
}) {
  return (
    <form style={{ width: 320, boxSizing: "border-box", font: "15px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12 }} onSubmit={(e) => e.preventDefault()}>
      <p style={{ margin: "0 0 14px", fontSize: 13, color: "#241430aa" }}>
        A real <code style={{ background: "#24143012", padding: "1px 5px", borderRadius: 4 }}>{`<button type="${type}">`}</code> inside a form — its type decides what it does when pressed.
      </p>
      <button
        type={type}
        disabled={disabled}
        style={{ font: "600 15px system-ui, sans-serif", padding: "11px 22px", borderRadius: 8, border: `2px solid ${accent}`, background: accent, color: "#FAF7F2", cursor: disabled ? "not-allowed" : "pointer", opacity: disabled ? 0.4 : 1 }}
      >
        {label}
      </button>
    </form>
  );
}
